handleMe(req) {
    if (!req.info?.sessionToken) {
      return Promise.reject(createSanitizedError(Parse.Error.INVALID_SESSION_TOKEN, 'Invalid session token', req.config));
    }
    const sessionToken = req.info.sessionToken;

    return rest.find(
        req.config,
        Auth.master(req.config),
        '_Session',
        { sessionToken },
        { include: 'user' },
        req.info.clientSDK,
        req.info.context
    )
    .then(response => {
      if (!response.results || response.results.length === 0 || !response.results[0].user) {
        throw createSanitizedError(Parse.Error.INVALID_SESSION_TOKEN, 'Invalid session token', req.config);
      }

      const user = response.results[0].user;
      // Send token back on the login, because SDKs expect that.
      user.sessionToken = sessionToken;

      // Remove hidden properties.
      UsersRouter.removeHiddenProperties(user);
      return { response: user };
    });
  }

