() => {
      let effectiveTrailingSlash = unref(props.trailingSlash) ?? options.trailingSlash;

      if (!to.value || isAbsoluteUrl.value || isHashLinkWithoutHashMode(to.value)) {
        return to.value as string;
      }

      if (isExternal.value) {
        let path;
        if (typeof to.value === 'object' && 'path' in to.value) {
          path = resolveRouteObject(to.value);
        } else {
          path = to.value;
        }

        let href;
        if (typeof path === 'object') {
          href = router.resolve(path).href;
        } else {
          href = path;
        }
        return applyTrailingSlashBehavior(href, effectiveTrailingSlash);
      }

      if (typeof to.value === 'object') {
        const resolved = router.resolve(to.value);
        return resolved?.href ?? null;
      }

      const joinedUrl = joinURL(config.app.baseURL, to.value);
      return applyTrailingSlashBehavior(joinedUrl, effectiveTrailingSlash);
    }

