      const effectiveTrailingSlash = unref(props.trailingSlash) ?? options.trailingSlash;
      if (!to.value || isAbsoluteUrl.value || isHashLinkWithoutHashMode(to.value)) {
        const raw = to.value as string;
        return typeof raw === 'string' ? sanitizeExternalHref(raw) : raw;
      }

      if (isExternal.value) {
        let path;
        if (typeof to.value === 'object' && 'path' in to.value) {
          path = resolveRouteObject(to.value);
        } else {
          path = to.value;
        }

        let href;
        if (typeof path === 'object') {
          const resolved = router.resolve(path);
          href = resolved ? resolved.href : path;
        } else {
          href = path;
        }

        const safe = typeof href === 'string' ? sanitizeExternalHref(href) : href;
        return safe === null ? null : applyTrailingSlashBehavior(safe, effectiveTrailingSlash);
      }

      if (typeof to.value === 'object') {
        const resolved = router.resolve(to.value);
        return resolved?.href ?? null;
      }

      const joined = joinURL(config.app.baseURL, to.value);
      return applyTrailingSlashBehavior(joined, effectiveTrailingSlash);
    }

