candidate_source:
function encodeURL(inputPath: string, shouldBeExternal: boolean = false): string {
  const urlObject = new URL(inputPath, 'http://localhost');
  let result: string;

  if (!shouldBeExternal) {
    // Collapse leading slashes to keep the redirect same-origin (CWE-601).
    const pathSegment = urlObject.pathname.replace(/^\/{2,}/, '/');
    result = pathSegment + urlObject.search + urlObject.hash;
    return result;
  }

  if (inputPath.startsWith('//')) {
    return urlObject.toString().replace(urlObject.protocol, '');
  }

  return urlObject.toString();
}

