        triggers.Types.afterFind,
        { file },
        config,
        req.auth
      );
      res.status(200);
      res.json(data);
    } catch (e) {
      const err = triggers.resolveError(e, {
        code: Parse.Error.SCRIPT_FAILED,
        message: 'Could not get file metadata.',
      });
      res.status(403);
      res.json({ code: err.code, error: err.message });
    }
  }

