function processCloning(childNode, parentNode, seenNodes) {
  // Check for circular reference.
  if (seenNodes == null) seenNodes = new Set()
  if (seenNodes.has(parentNode)) return

  seenNodes.add(parentNode)
  for (const propName in parentNode) {
    if (propName === 'isBrowserView') continue
    if (!hasProp.call(parentNode, propName)) continue
    if (propName in childNode && propName !== 'webPreferences') continue

    const propValue = parentNode[propName]
    if (typeof propValue === 'object') {
      childNode[propName] = mergeOptions(childNode[propName] || {}, propValue, seenNodes)
    } else {
      childNode[propName] = propValue
    }
  }
  seenNodes.delete(parentNode)

  return childNode
}

