function computeQueryComplexity(queryOperation, schemaFragments, constraintLimits = {}) {
  let deepestLevel = 0;
  let fieldCount = 0;
  const fragmentMap = new Map();
  const { maxDepth: allowedDepth, maxFields: allowedFields } = constraintLimits;

  function traverseSelectionSet(selectionSet, currentDepth, encounteredFragments) {
    if (!selectionSet) {
      return;
    }
    if (
      (allowedFields !== undefined && allowedFields !== -1 && fieldCount > allowedFields) ||
      (allowedDepth !== undefined && allowedDepth !== -1 && deepestLevel > allowedDepth)
    ) {
      return;
    }
    for (const selectionItem of selectionSet.selections) {
      if (selectionItem.kind === 'Field') {
        fieldCount++;
        const nextDepth = currentDepth + 1;
        if (nextDepth > deepestLevel) {
          deepestLevel = nextDepth;
        }
        if (selectionItem.selectionSet) {
          traverseSelectionSet(selectionItem.selectionSet, nextDepth, encounteredFragments);
        }
      } else if (selectionItem.kind === 'InlineFragment') {
        traverseSelectionSet(selectionItem.selectionSet, currentDepth, encounteredFragments);
      } else if (selectionItem.kind === 'FragmentSpread') {
        const fragmentName = selectionItem.name.value;
        if (fragmentMap.has(fragmentName)) {
          const cachedData = fragmentMap.get(fragmentName);
          fieldCount += cachedData.fields;
          const adjustedDepthLevel = currentDepth + cachedData.maxDepthDelta;
          if (adjustedDepthLevel > deepestLevel) {
            deepestLevel = adjustedDepthLevel;
          }
          continue;
        }
        if (encounteredFragments.has(fragmentName)) {
          continue;
        }
        const fragmentDefinition = schemaFragments[fragmentName];
        if (fragmentDefinition) {
          if (
            (allowedFields !== undefined && allowedFields !== -1 && fieldCount > allowedFields) ||
            (allowedDepth !== undefined && allowedDepth !== -1 && deepestLevel > allowedDepth)
          ) {
            continue;
          }
          encounteredFragments.add(fragmentName);
          const tempFieldCount = fieldCount;
          const tempDeepestLevel = deepestLevel;
          deepestLevel = currentDepth;
          traverseSelectionSet(fragmentDefinition.selectionSet, currentDepth, encounteredFragments);
          const fieldsContribution = fieldCount - tempFieldCount;
          const maxDepthDelta = deepestLevel - currentDepth;
          fragmentMap.set(fragmentName, { fields: fieldsContribution, maxDepthDelta });
          deepestLevel = Math.max(tempDeepestLevel, deepestLevel);
          encounteredFragments.delete(fragmentName);
        }
      }
    }
  }

  traverseSelectionSet(queryOperation.selectionSet, 0, new Set());

  return { depth: deepestLevel, fields: fieldCount };
}

