function isFileLoadingAllowed(config: ResolvedConfig, filePath: string): boolean {
  const { fs } = config.server

  if (!fs.strict) {
    return true;
  }

  // NOTE: `fs.readFile('/foo.png/')` tries to load `'/foo.png'`
  // so we should check the path without trailing slash
  let pathToCheck = filePath;
  if (filePath.endsWith('/')) {
    pathToCheck = filePath.slice(0, -1);
  }

  if (config.fsDenyGlob(pathToCheck)) {
    return false;
  }

  if (config.safeModulePaths.has(filePath)) {
    return true;
  }

  const allowedByTarget = fs.allow.some((uri) => isFileInTargetPath(uri, filePath));
  if (allowedByTarget) {
    return true;
  }

  return false;
}

