const _normalizeAddress = (inputAddr) => {
    let processedAddr = (inputAddr || '').toString().trim();

    let atIndex = processedAddr.lastIndexOf('@');
    if (atIndex < 0) {
        // Bare username
        return processedAddr;
    }

    let usernamePart = processedAddr.substring(0, atIndex);
    let domainPart = processedAddr.substring(atIndex + 1);

    // Usernames are not touched and are kept as is even if these include unicode
    // Domains are punycoded by default
    // 'jõgeva.ee' will be converted to 'xn--jgeva-dua.ee'
    // non-unicode domains are left as is

    let finalDomain = punycode.toASCII(domainPart.toLowerCase());
    return usernamePart + '@' + finalDomain;
}

