  let proxyObj = confProxy;
  if (!proxyObj && proxyObj !== false) {
    const proxyUrlString = getProxyForUrl(loc);
    if (proxyUrlString) {
      proxyObj = new URL(proxyUrlString);
    }
  }
  if (proxyObj) {
    // Basic proxy authorization
    if (proxyObj.username) {
      proxyObj.auth = (proxyObj.username || '') + ':' + (proxyObj.password || '');
    }

    if (proxyObj.auth) {
      // Support proxy auth object form
      const validAuth = Boolean(proxyObj.auth.username || proxyObj.auth.password);

      if (validAuth) {
        proxyObj.auth = (proxyObj.auth.username || '') + ':' + (proxyObj.auth.password || '');
      } else if (typeof proxyObj.auth === 'object') {
        throw new AxiosError('Invalid proxy authorization', AxiosError.ERR_BAD_OPTION, { proxy: proxyObj });
      }

      const base64Encoded = Buffer.from(proxyObj.auth, 'utf8').toString('base64');

      opts.headers['Proxy-Authorization'] = 'Basic ' + base64Encoded;
    }

    opts.headers.host = opts.hostname + (opts.port ? ':' + opts.port : '');
    const proxyHostName = proxyObj.hostname || proxyObj.host;
    opts.hostname = proxyHostName;
    // Replace 'host' since opts is not a URL object
    opts.host = proxyHostName;
    opts.port = proxyObj.port;
    opts.path = loc;
    if (proxyObj.protocol) {
      opts.protocol = proxyObj.protocol.includes(':') ? proxyObj.protocol : `${proxyObj.protocol}:`;
    }
  }

  opts.beforeRedirects.proxy = function beforeRedirect(redirectOpts) {
    // Configure proxy for redirected request, passing the original config proxy to apply
    // the exact same logic as if the redirected request was performed by axios directly.
    setProxy(redirectOpts, confProxy, redirectOpts.href);
  };
}

