candidate_source:
const _normalizeAddress = (address) => {
  let strAddress = (address || '').toString().trim();

  const lastAtIndex = strAddress.lastIndexOf('@');
  if (lastAtIndex < 0) {
    return strAddress;
  }

  let userPart = strAddress.substring(0, lastAtIndex);
  let domainPart = strAddress.substring(lastAtIndex + 1);

  return userPart + '@' + punycode.toASCII(domainPart.toLowerCase());
};

